//! `brain`: a shadow assistant that captures what you type and makes it searchable.
//!
//! Pipeline: [`capture`] (keystrokes + focus → append-only [`eventlog`]) →
//! [`ingest`] (log → SQLite [`store`]) → query.

pub mod capture;
pub mod datadir;
pub mod event;
pub mod eventlog;
pub mod ingest;
pub mod store;
pub mod timefmt;

//! `kill -9` at random moments, then restart: no corruption, no gaps, no duplicates.
//!
//! Drives the real `brain` binary with its synthetic input source (the evdev
//! read is the only part replaced), so it runs unattended and without root.

use brain::eventlog::LogReader;
use brain::ingest::CHECKPOINT_INTERVAL_MS;
use rusqlite::Connection;
use std::collections::HashMap;
use std::path::Path;
use std::process::{Child, Command, Stdio};
use std::time::{Duration, Instant};

fn spawn_brain(dir: &Path, rate: u32) -> Child {
    Command::new(env!("CARGO_BIN_EXE_brain"))
        .args(["run", "--synthetic", &rate.to_string(), "--data-dir"])
        .arg(dir)
        .stdout(Stdio::null())
        .stderr(Stdio::null())
        .spawn()
        .expect("spawn brain")
}

/// xorshift64*: deterministic, dependency-free randomness for kill timing.
struct Rng(u64);
impl Rng {
    fn next(&mut self) -> u64 {
        self.0 ^= self.0 >> 12;
        self.0 ^= self.0 << 25;
        self.0 ^= self.0 >> 27;
        self.0.wrapping_mul(0x2545_F491_4F6C_DD1D)
    }
    fn range_ms(&mut self, lo: u64, hi: u64) -> u64 {
        lo + self.next() % (hi - lo)
    }
}

fn wait_for_file(p: &Path) {
    let t = Instant::now();
    while !p.exists() {
        assert!(
            t.elapsed() < Duration::from_secs(10),
            "{} never appeared",
            p.display()
        );
        std::thread::sleep(Duration::from_millis(10));
    }
}

#[test]
fn kill_dash_nine_never_corrupts() {
    let tmp = tempfile::tempdir().unwrap();
    let dir = tmp.path().join("data");
    let log = dir.join("events.jsonl");
    let db = dir.join("brain.db");
    let mut rng = Rng(0x9E37_79B9_7F4A_7C15);
    let mut torn_tails = 0;

    for _ in 0..25 {
        // A high key rate makes it likely that some kills land mid-write.
        let mut child = spawn_brain(&dir, 3000);
        wait_for_file(&db);
        std::thread::sleep(Duration::from_millis(rng.range_ms(50, 1500)));
        child.kill().unwrap(); // SIGKILL
        child.wait().unwrap();

        let bytes = std::fs::read(&log).unwrap();
        if bytes.last().is_some_and(|&b| b != b'\n') {
            torn_tails += 1;
        }
        // The database is never corrupt, and its offset is at a line boundary
        // inside the log.
        let c = Connection::open(&db).unwrap();
        let ok: String = c
            .query_row("PRAGMA integrity_check", [], |r| r.get(0))
            .unwrap();
        assert_eq!(ok, "ok");
        let off: i64 = c
            .query_row("SELECT log_offset FROM ingest_state", [], |r| r.get(0))
            .unwrap();
        let off = off as usize;
        assert!(off <= bytes.len());
        assert!(
            off == 0 || bytes[off - 1] == b'\n',
            "offset {off} not at a line boundary"
        );
    }

    // A final clean run: start, let ingest catch up, stop with SIGTERM.
    let child = spawn_brain(&dir, 50);
    std::thread::sleep(Duration::from_millis(1500));
    // SAFETY: sending SIGTERM to our own child.
    unsafe { libc::kill(child.id() as i32, libc::SIGTERM) };
    let out = child.wait_with_output().unwrap();
    assert!(out.status.success(), "clean stop must exit 0");

    // Every line in the log is a complete, valid event.
    let mut reader = LogReader::open(&log, 0).unwrap();
    let mut events = Vec::new();
    while let Some(line) = reader.next_line().unwrap() {
        let ev = line
            .event
            .unwrap_or_else(|| panic!("invalid line at offset {}", line.offset));
        events.push((line.offset, ev));
    }
    let log_len = std::fs::metadata(&log).unwrap().len();
    assert_eq!(reader.offset(), log_len, "no torn tail after a clean stop");
    assert!(
        events.len() > 1000,
        "expected plenty of events, got {}",
        events.len()
    );

    // Ingest covered the whole log...
    let c = Connection::open(&db).unwrap();
    let off: i64 = c
        .query_row("SELECT log_offset FROM ingest_state", [], |r| r.get(0))
        .unwrap();
    assert_eq!(off as u64, log_len);

    // ...and its derived rows are exactly what one uninterrupted pass over the
    // log produces: across 25 kills, nothing was skipped or applied twice.
    let mut expected: Vec<(String, String, i64)> = Vec::new();
    let mut last: HashMap<String, i64> = HashMap::new();
    for (offset, ev) in &events {
        for app in ["*", ev.app.as_str()] {
            let due = last
                .get(app)
                .is_none_or(|prev| (ev.ts - prev).abs() >= CHECKPOINT_INTERVAL_MS);
            if due {
                let ts = brain::timefmt::format_ms(ev.ts);
                // PRIMARY KEY (app, ts): a same-millisecond duplicate is ignored.
                if !expected.iter().any(|(a, t, _)| a == app && *t == ts) {
                    expected.push((app.to_string(), ts, *offset as i64));
                }
                last.insert(app.to_string(), ev.ts);
            }
        }
    }
    let mut stmt = c
        .prepare("SELECT app, ts, byte_offset FROM log_checkpoints ORDER BY byte_offset, app")
        .unwrap();
    let actual: Vec<(String, String, i64)> = stmt
        .query_map([], |r| Ok((r.get(0)?, r.get(1)?, r.get(2)?)))
        .unwrap()
        .collect::<Result<_, _>>()
        .unwrap();
    expected.sort_by(|a, b| (a.2, &a.0).cmp(&(b.2, &b.0)));
    assert_eq!(actual, expected);

    eprintln!(
        "{} events, {} torn tails repaired across 25 kills",
        events.len(),
        torn_tails
    );
}

//! A synthetic input source for tests and benchmarks (`brain run --synthetic RATE`).
//!
//! It types a fixed corpus as raw evdev key transitions, at `RATE` key presses
//! per second, through the same [`KeyProcessor`] → [`Recorder`] → log → ingest
//! path as real input. Only the evdev device read is replaced. Crash-safety,
//! consistency and resource tests can therefore run unattended, without root
//! access to `/dev/uinput`.

use super::keys::{KeyOut, KeyProcessor};
use super::recorder::Recorder;
use crate::timefmt::now_ms;
use std::sync::Arc;
use std::sync::atomic::{AtomicBool, Ordering};
use std::time::{Duration, Instant};

pub const SYNTHETIC_APP: &str = "synthetic";
pub const SYNTHETIC_WINDOW: &str = "corpus.txt";

const CORPUS: &str = "the migration is blocked on the schema change. \
    Dana asked whether we can ship search on Friday; I said yes if the index rebuild \
    finishes overnight. Next: run the backfill on prod and check the error rate.\n";

const KEY_LEFTSHIFT: u16 = 42;
const KEY_BACKSPACE: u16 = 14;

/// evdev keycode and whether Shift is needed, for the US layout.
pub fn us_keycode(c: char) -> Option<(u16, bool)> {
    const LETTERS: [u16; 26] = [
        30, 48, 46, 32, 18, 33, 34, 35, 23, 36, 37, 38, 50, 49, 24, 25, 16, 19, 31, 20, 22, 47, 17,
        45, 21, 44,
    ];
    Some(match c {
        'a'..='z' => (LETTERS[(c as u8 - b'a') as usize], false),
        'A'..='Z' => (LETTERS[(c as u8 - b'A') as usize], true),
        '1'..='9' => (2 + (c as u8 - b'1') as u16, false),
        '0' => (11, false),
        ' ' => (57, false),
        '\n' => (28, false),
        '.' => (52, false),
        ',' => (51, false),
        ';' => (39, false),
        ':' => (39, true),
        '?' => (53, true),
        '-' => (12, false),
        '\'' => (40, false),
        _ => return None,
    })
}

/// Types the corpus until `stop` is set. Every 50th word gets a typo that is
/// immediately corrected with Backspace, to exercise editing keys.
pub fn run(mut keys: KeyProcessor, recorder: Arc<Recorder>, rate_hz: f64, stop: Arc<AtomicBool>) {
    recorder.set_focus(SYNTHETIC_APP, SYNTHETIC_WINDOW);
    let period = Duration::from_secs_f64(1.0 / rate_hz.max(0.1));
    let start = Instant::now();
    let mut presses: u64 = 0;
    let mut words: u64 = 0;
    let mut emit = |k: KeyOut| recorder.key(k.ts, k.key, k.mods, k.repeat);
    'outer: loop {
        for c in CORPUS.chars() {
            let Some((code, shift)) = us_keycode(c) else {
                continue;
            };
            let mut strokes: Vec<(u16, bool)> = vec![(code, shift)];
            if c == ' ' {
                words += 1;
                if words.is_multiple_of(50) {
                    strokes.insert(0, (us_keycode('x').unwrap().0, false));
                    strokes.insert(1, (KEY_BACKSPACE, false));
                }
            }
            for (code, shift) in strokes {
                if stop.load(Ordering::Relaxed) {
                    break 'outer;
                }
                // Pace against the start time so the long-run rate is exact.
                presses += 1;
                let due = start + period.mul_f64(presses as f64);
                if let Some(wait) = due.checked_duration_since(Instant::now()) {
                    std::thread::sleep(wait);
                }
                let ts = now_ms();
                if shift {
                    keys.key(0, KEY_LEFTSHIFT, 1, ts, &mut emit);
                }
                keys.key(0, code, 1, ts, &mut emit);
                keys.key(0, code, 0, ts, &mut emit);
                if shift {
                    keys.key(0, KEY_LEFTSHIFT, 0, ts, &mut emit);
                }
            }
        }
    }
    keys.release_all();
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn corpus_is_fully_typeable() {
        for c in CORPUS.chars() {
            assert!(us_keycode(c).is_some(), "no keycode for {c:?}");
        }
    }
}

use anyhow::{Result, bail};
use brain::datadir::DataDir;
use clap::{Parser, Subcommand};
use std::path::PathBuf;
use std::process::ExitCode;

/// A shadow assistant: captures what you type and makes it searchable.
#[derive(Parser)]
#[command(name = "brain", version, about)]
struct Cli {
    /// Directory holding the capture log and the index.
    #[arg(
        long,
        global = true,
        value_name = "DIR",
        default_value = "./brain-data"
    )]
    data_dir: PathBuf,

    #[command(subcommand)]
    command: Command,
}

#[derive(Subcommand)]
enum Command {
    /// Capture keystrokes and focus changes until stopped (Ctrl+C / SIGTERM).
    Run {
        /// Test hook: type a built-in corpus at RATE keys/s instead of reading
        /// input devices (no root or desktop needed).
        #[arg(long, value_name = "RATE", hide = true)]
        synthetic: Option<f64>,
    },
    /// Query what has been captured. Safe to run while `brain run` is running.
    Query {
        #[command(subcommand)]
        query: Query,
    },
}

#[derive(Subcommand)]
enum Query {
    /// Full-text search over writing sessions.
    Search {
        /// One or more words; all must appear in the same session (case-insensitive).
        query: String,
        #[arg(long, value_name = "A")]
        app: Option<String>,
        #[arg(long, value_name = "T")]
        from: Option<String>,
        #[arg(long, value_name = "T")]
        to: Option<String>,
        #[arg(long, value_name = "N", default_value_t = 20)]
        limit: usize,
    },
    /// The raw typed character stream of an app over a time window.
    Text {
        #[arg(long, value_name = "A")]
        app: String,
        /// End of a 10-minute window (default: now).
        #[arg(long, value_name = "T", conflicts_with_all = ["from", "to"])]
        at: Option<String>,
        #[arg(long, value_name = "T")]
        from: Option<String>,
        #[arg(long, value_name = "T")]
        to: Option<String>,
    },
}

fn main() -> ExitCode {
    let cli = Cli::parse();
    match dispatch(cli) {
        Ok(()) => ExitCode::SUCCESS,
        Err(e) => {
            eprintln!("brain: error: {e:#}");
            ExitCode::FAILURE
        }
    }
}

fn dispatch(cli: Cli) -> Result<()> {
    let data_dir = DataDir::new(cli.data_dir);
    match cli.command {
        Command::Run { synthetic } => {
            let opts = brain::capture::RunOptions {
                synthetic_rate: synthetic,
            };
            brain::capture::run(&data_dir, &opts)
        }
        Command::Query { .. } => {
            data_dir.ensure_exists()?;
            bail!("`brain query` is not implemented yet (stage 2)")
        }
    }
}

//! The SQLite index: derived from the capture log and rebuildable from it.
//!
//! WAL mode gives the concurrency model `brain` needs. The single writer (the
//! ingest thread inside `brain run`) never blocks readers. Each `brain query`
//! reads a consistent snapshot as of the start of its read transaction. Ingest
//! advances `ingest_state.log_offset` in the same transaction as the rows it
//! derives from those log bytes, so after a crash the index and the offset
//! always agree.
//!
//! `synchronous = NORMAL` is safe against corruption in WAL mode. A power loss
//! may drop the last few committed transactions, and the log is fsync'd
//! independently, so ingest simply re-derives them on the next start.

use anyhow::{Context, Result, bail};
use rusqlite::{Connection, OpenFlags, OptionalExtension};
use std::path::Path;
use std::time::Duration;

/// Bumped whenever the schema changes; see [`migrate`].
pub const SCHEMA_VERSION: i64 = 1;

const SCHEMA_V1: &str = r#"
CREATE TABLE sessions (
  id                 INTEGER PRIMARY KEY,
  app                TEXT NOT NULL,
  window             TEXT NOT NULL,
  started_at         TEXT NOT NULL,              -- RFC 3339 UTC, same format as the log
  ended_at           TEXT,
  status             TEXT NOT NULL DEFAULT 'open' CHECK (status IN ('open', 'closed')),
  tier_used          INTEGER,
  reconstructed_text TEXT,
  start_offset       INTEGER NOT NULL DEFAULT 0  -- log byte offset of the session's first event
);
CREATE INDEX idx_sessions_app_time ON sessions(app, started_at);
CREATE INDEX idx_sessions_status ON sessions(status);

CREATE VIRTUAL TABLE sessions_fts USING fts5(
  reconstructed_text, content='sessions', content_rowid='id',
  tokenize='porter unicode61'
);
CREATE TRIGGER sessions_ai AFTER INSERT ON sessions BEGIN
  INSERT INTO sessions_fts(rowid, reconstructed_text) VALUES (new.id, new.reconstructed_text);
END;
CREATE TRIGGER sessions_ad AFTER DELETE ON sessions BEGIN
  INSERT INTO sessions_fts(sessions_fts, rowid, reconstructed_text)
    VALUES ('delete', old.id, old.reconstructed_text);
END;
CREATE TRIGGER sessions_au AFTER UPDATE OF reconstructed_text ON sessions BEGIN
  INSERT INTO sessions_fts(sessions_fts, rowid, reconstructed_text)
    VALUES ('delete', old.id, old.reconstructed_text);
  INSERT INTO sessions_fts(rowid, reconstructed_text) VALUES (new.id, new.reconstructed_text);
END;

CREATE TABLE ingest_state (
  id         INTEGER PRIMARY KEY CHECK (id = 1),
  log_offset INTEGER NOT NULL DEFAULT 0          -- bytes of the capture log already ingested
);
INSERT INTO ingest_state (id, log_offset) VALUES (1, 0);

-- Seek points into the capture log. app = '*' rows are global (any app).
CREATE TABLE log_checkpoints (
  app         TEXT NOT NULL,
  ts          TEXT NOT NULL,
  byte_offset INTEGER NOT NULL,
  PRIMARY KEY (app, ts)
);
"#;

/// The app value used for global (all-app) checkpoints.
pub const GLOBAL_CHECKPOINT_APP: &str = "*";

/// Opens the database for the writer (`brain run`), creating and migrating it.
pub fn open_writer(path: &Path) -> Result<Connection> {
    let conn =
        Connection::open(path).with_context(|| format!("opening database {}", path.display()))?;
    conn.busy_timeout(Duration::from_secs(5))?;
    let mode: String = conn.query_row("PRAGMA journal_mode = WAL", [], |r| r.get(0))?;
    if !mode.eq_ignore_ascii_case("wal") {
        bail!(
            "could not enable WAL mode on {} (got {mode})",
            path.display()
        );
    }
    conn.execute_batch(
        "PRAGMA synchronous = NORMAL;
         PRAGMA foreign_keys = ON;
         PRAGMA cache_size = -1024;", // 1 MiB page cache: keeps `run` well inside its memory budget
    )?;
    migrate(&conn).with_context(|| format!("migrating database {}", path.display()))?;
    Ok(conn)
}

/// Opens the database read-only for `brain query`. Safe while `brain run` writes.
pub fn open_reader(path: &Path) -> Result<Connection> {
    let conn = Connection::open_with_flags(
        path,
        OpenFlags::SQLITE_OPEN_READ_ONLY | OpenFlags::SQLITE_OPEN_NO_MUTEX,
    )
    .with_context(|| format!("opening database {}", path.display()))?;
    conn.busy_timeout(Duration::from_secs(5))?;
    conn.execute_batch("PRAGMA query_only = ON; PRAGMA cache_size = -1024;")?;
    let version: i64 = conn.query_row("PRAGMA user_version", [], |r| r.get(0))?;
    if version != SCHEMA_VERSION {
        bail!(
            "database {} has schema version {version}, this brain expects {SCHEMA_VERSION} \
             (restart `brain run` to migrate it)",
            path.display()
        );
    }
    Ok(conn)
}

fn migrate(conn: &Connection) -> Result<()> {
    let version: i64 = conn.query_row("PRAGMA user_version", [], |r| r.get(0))?;
    match version {
        0 => {
            let tx = conn.unchecked_transaction()?;
            tx.execute_batch(SCHEMA_V1)?;
            tx.pragma_update(None, "user_version", SCHEMA_VERSION)?;
            tx.commit()?;
            Ok(())
        }
        SCHEMA_VERSION => Ok(()),
        v => bail!("database schema version {v} is newer than this brain ({SCHEMA_VERSION})"),
    }
}

pub fn ingest_offset(conn: &Connection) -> Result<u64> {
    let off: i64 = conn.query_row(
        "SELECT log_offset FROM ingest_state WHERE id = 1",
        [],
        |r| r.get(0),
    )?;
    Ok(off as u64)
}

pub fn set_ingest_offset(conn: &Connection, offset: u64) -> Result<()> {
    conn.execute(
        "UPDATE ingest_state SET log_offset = ?1 WHERE id = 1",
        [offset as i64],
    )?;
    Ok(())
}

pub fn insert_checkpoint(conn: &Connection, app: &str, ts: &str, offset: u64) -> Result<()> {
    conn.prepare_cached(
        "INSERT OR IGNORE INTO log_checkpoints (app, ts, byte_offset) VALUES (?1, ?2, ?3)",
    )?
    .execute(rusqlite::params![app, ts, offset as i64])?;
    Ok(())
}

/// Latest checkpoint timestamp per app, used to resume checkpoint spacing after a restart.
pub fn latest_checkpoints(conn: &Connection) -> Result<Vec<(String, String)>> {
    let mut stmt = conn.prepare("SELECT app, MAX(ts) FROM log_checkpoints GROUP BY app")?;
    let rows = stmt
        .query_map([], |r| Ok((r.get::<_, String>(0)?, r.get::<_, String>(1)?)))?
        .collect::<rusqlite::Result<Vec<_>>>()?;
    Ok(rows)
}

/// Byte offset of the latest global checkpoint at or before `ts`, or 0.
pub fn seek_offset_before(conn: &Connection, ts: &str) -> Result<u64> {
    let off: Option<i64> = conn
        .query_row(
            "SELECT byte_offset FROM log_checkpoints WHERE app = ?1 AND ts <= ?2
             ORDER BY ts DESC LIMIT 1",
            rusqlite::params![GLOBAL_CHECKPOINT_APP, ts],
            |r| r.get(0),
        )
        .optional()?;
    Ok(off.unwrap_or(0) as u64)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn creates_schema_and_is_idempotent() {
        let tmp = tempfile::tempdir().unwrap();
        let p = tmp.path().join("b.db");
        let c = open_writer(&p).unwrap();
        assert_eq!(ingest_offset(&c).unwrap(), 0);
        set_ingest_offset(&c, 1234).unwrap();
        drop(c);
        let c = open_writer(&p).unwrap();
        assert_eq!(ingest_offset(&c).unwrap(), 1234);
        let r = open_reader(&p).unwrap();
        assert_eq!(ingest_offset(&r).unwrap(), 1234);
        assert!(
            r.execute("UPDATE ingest_state SET log_offset = 0", [])
                .is_err()
        );
    }

    #[test]
    fn fts_triggers_keep_index_in_sync() {
        let tmp = tempfile::tempdir().unwrap();
        let c = open_writer(&tmp.path().join("b.db")).unwrap();
        c.execute(
            "INSERT INTO sessions (app, window, started_at, reconstructed_text)
             VALUES ('a', 'w', '2026-01-01T00:00:00.000Z', 'the migration is blocked')",
            [],
        )
        .unwrap();
        let hits = |q: &str| -> i64 {
            c.query_row(
                "SELECT count(*) FROM sessions_fts WHERE sessions_fts MATCH ?1",
                [q],
                |r| r.get(0),
            )
            .unwrap()
        };
        assert_eq!(hits("migration"), 1);
        c.execute(
            "UPDATE sessions SET reconstructed_text = 'nothing here'",
            [],
        )
        .unwrap();
        assert_eq!(hits("migration"), 0);
        assert_eq!(hits("nothing"), 1);
        c.execute("DELETE FROM sessions", []).unwrap();
        assert_eq!(hits("nothing"), 0);
    }

    #[test]
    fn checkpoint_seek() {
        let tmp = tempfile::tempdir().unwrap();
        let c = open_writer(&tmp.path().join("b.db")).unwrap();
        insert_checkpoint(&c, "*", "2026-01-01T00:00:00.000Z", 0).unwrap();
        insert_checkpoint(&c, "*", "2026-01-01T00:00:05.000Z", 500).unwrap();
        insert_checkpoint(&c, "*", "2026-01-01T00:00:10.000Z", 900).unwrap();
        insert_checkpoint(&c, "*", "2026-01-01T00:00:10.000Z", 999).unwrap(); // ignored duplicate
        assert_eq!(
            seek_offset_before(&c, "2026-01-01T00:00:07.000Z").unwrap(),
            500
        );
        assert_eq!(
            seek_offset_before(&c, "2026-01-01T00:00:10.000Z").unwrap(),
            900
        );
        assert_eq!(
            seek_offset_before(&c, "2025-01-01T00:00:00.000Z").unwrap(),
            0
        );
        let latest = latest_checkpoints(&c).unwrap();
        assert_eq!(
            latest,
            vec![("*".into(), "2026-01-01T00:00:10.000Z".into())]
        );
    }
}

