1	//! Ingest: tails the capture log into the SQLite index.
2	//!
3	//! Each [`Ingester::step`] reads a bounded batch of complete log lines starting at
4	//! the persisted offset. It writes everything it derives from them and the new
5	//! offset in **one transaction**. If the process dies before the commit, nothing
6	//! from the batch is visible and the next start re-reads the same bytes. If it
7	//! dies after the commit, the offset already covers the batch. Either way there
8	//! are no gaps and no duplicates.
9	//!
10	//! Stage 1 derives log checkpoints (seek points for `query text`). Session
11	//! reconstruction is added on top of the same step in a later stage.
12	
13	use crate::eventlog::LogReader;
14	use crate::store::{self, GLOBAL_CHECKPOINT_APP};
15	use crate::timefmt::{self, Millis};
16	use anyhow::{Context, Result};
17	use rusqlite::Connection;
18	use std::collections::HashMap;
19	use std::path::{Path, PathBuf};
20	
21	/// Minimum spacing between two checkpoints for the same app, in log time.
22	pub const CHECKPOINT_INTERVAL_MS: Millis = 5_000;
23	/// Upper bound on lines per transaction, which bounds memory use and commit latency.
24	pub const MAX_LINES_PER_STEP: usize = 5_000;
25	
26	pub struct Ingester {
27	    conn: Connection,
28	    log_path: PathBuf,
29	    offset: u64,
30	    last_checkpoint: HashMap<String, Millis>,
31	}
32	
33	#[derive(Debug, Default, Clone, Copy, PartialEq, Eq)]
34	pub struct StepStats {
35	    pub lines: usize,
36	    pub invalid_lines: usize,
37	    pub checkpoints: usize,
38	}
39	
40	impl Ingester {
41	    pub fn new(conn: Connection, log_path: &Path) -> Result<Self> {
42	        let mut offset = store::ingest_offset(&conn)?;
43	        // After a power loss the log's un-fsync'd tail can vanish while the
44	        // index (committed earlier) still points past it. Resume from the end
45	        // of what survived instead of seeking beyond EOF.
46	        let log_len = std::fs::metadata(log_path).map(|m| m.len()).unwrap_or(0);
47	        if offset > log_len {
48	            eprintln!(
49	                "brain: ingest offset {offset} is past the end of the log ({log_len} bytes); \
50	                 resuming from the end"
51	            );
52	            offset = log_len;
53	            store::set_ingest_offset(&conn, offset)?;
54	        }
55	        let mut last_checkpoint = HashMap::new();
56	        for (app, ts) in store::latest_checkpoints(&conn)? {
57	            if let Ok(ms) = timefmt::parse_rfc3339_ms(&ts) {
58	                last_checkpoint.insert(app, ms);
59	            }
60	        }
61	        Ok(Self {
62	            conn,
63	            log_path: log_path.to_owned(),
64	            offset,
65	            last_checkpoint,
66	        })
67	    }
68	
69	    pub fn offset(&self) -> u64 {
70	        self.offset
71	    }
72	
73	    /// Ingests at most [`MAX_LINES_PER_STEP`] new complete lines.
74	    /// Returns `lines == 0` when caught up.
75	    pub fn step(&mut self) -> Result<StepStats> {
76	        if !self.log_path.exists() {
77	            return Ok(StepStats::default());
78	        }
79	        let mut reader = LogReader::open(&self.log_path, self.offset)?;
80	        let mut stats = StepStats::default();
81	        // Checkpoint decisions are staged and only become the in-memory state
82	        // once the transaction commits, so a failed commit cannot desync them.
83	        let mut staged: HashMap<String, Millis> = HashMap::new();
84	
85	        let tx = self
86	            .conn
87	            .transaction()
88	            .context("starting ingest transaction")?;
89	        while stats.lines < MAX_LINES_PER_STEP {
90	            let Some(line) = reader.next_line()? else {
91	                break;
92	            };
93	            stats.lines += 1;
94	            let Some(event) = line.event else {
95	                stats.invalid_lines += 1;
96	                continue;
97	            };
98	            for app in [GLOBAL_CHECKPOINT_APP, event.app.as_str()] {
99	                let last = staged
100	                    .get(app)
101	                    .or_else(|| self.last_checkpoint.get(app))
102	                    .copied();
103	                if checkpoint_due(last, event.ts) {
104	                    store::insert_checkpoint(&tx, app, &timefmt::format_ms(event.ts), line.offset)?;
105	                    staged.insert(app.to_owned(), event.ts);
106	                    stats.checkpoints += 1;
107	                }
108	            }
109	        }
110	        if stats.lines == 0 {
111	            return Ok(stats); // nothing read: dropping `tx` is a no-op rollback
112	        }
113	        let new_offset = reader.offset();
114	        store::set_ingest_offset(&tx, new_offset)?;
115	        tx.commit().context("committing ingest transaction")?;
116	
117	        self.offset = new_offset;
118	        self.last_checkpoint.extend(staged);
119	        Ok(stats)
120	    }
121	
122	    pub fn connection(&self) -> &Connection {
123	        &self.conn
124	    }
125	
126	    /// Steps until caught up with the log (or `max_steps` reached).
127	    pub fn catch_up(&mut self, max_steps: usize) -> Result<StepStats> {
128	        let mut total = StepStats::default();
129	        for _ in 0..max_steps {
130	            let s = self.step()?;
131	            total.lines += s.lines;
132	            total.invalid_lines += s.invalid_lines;
133	            total.checkpoints += s.checkpoints;
134	            if s.lines < MAX_LINES_PER_STEP {
135	                break;
136	            }
137	        }
138	        Ok(total)
139	    }
140	}
141	
142	/// A new checkpoint is due when none exists yet for this app, or the last one is
143	/// at least [`CHECKPOINT_INTERVAL_MS`] away in log time. The distance is absolute
144	/// so that a backwards clock jump (NTP, manual change) cannot suppress
145	/// checkpoints until the clock catches up again.
146	fn checkpoint_due(last: Option<Millis>, ts: Millis) -> bool {
147	    match last {
148	        None => true,
149	        Some(prev) => (ts - prev).abs() >= CHECKPOINT_INTERVAL_MS,
150	    }
151	}
152	
153	#[cfg(test)]
154	mod tests {
155	    use super::*;
156	    use crate::event::{Event, EventKind};
157	    use crate::eventlog::LogWriter;
158	    use std::io::Write;
159	
160	    fn ev(ts: Millis, app: &str) -> Event {
161	        Event {
162	            ts,
163	            app: app.into(),
164	            kind: EventKind::Key {
165	                key: "a".into(),
166	                mods: vec![],
167	                repeat: false,
168	                window: "w".into(),
169	            },
170	        }
171	    }
172	
173	    fn count(conn: &Connection, sql: &str) -> i64 {
174	        conn.query_row(sql, [], |r| r.get(0)).unwrap()
175	    }
176	
177	    #[test]
178	    fn ingests_and_checkpoints_per_app_and_globally() {
179	        let tmp = tempfile::tempdir().unwrap();
180	        let log = tmp.path().join("events.jsonl");
181	        let mut w = LogWriter::open(&log).unwrap();
182	        // 20 s of events alternating between two apps, one per second.
183	        for i in 0..20 {
184	            w.append(&ev(
185	                1_000_000 + i * 1000,
186	                if i % 2 == 0 { "a" } else { "b" },
187	            ))
188	            .unwrap();
189	        }
190	        let mut ing =
191	            Ingester::new(store::open_writer(&tmp.path().join("b.db")).unwrap(), &log).unwrap();
192	        let s = ing.catch_up(10).unwrap();
193	        assert_eq!(s.lines, 20);
194	        assert_eq!(ing.offset(), w.len());
195	        let c = ing.connection();
196	        assert_eq!(
197	            count(c, "SELECT log_offset FROM ingest_state"),
198	            w.len() as i64
199	        );
200	        // Global: t=0,5,10,15 s. Per app (events every 2 s): a at 0,6,12,18; b at 1,7,13,19.
201	        assert_eq!(
202	            count(c, "SELECT count(*) FROM log_checkpoints WHERE app='*'"),
203	            4
204	        );
205	        assert_eq!(
206	            count(c, "SELECT count(*) FROM log_checkpoints WHERE app='a'"),
207	            4
208	        );
209	        assert_eq!(
210	            count(c, "SELECT count(*) FROM log_checkpoints WHERE app='b'"),
211	            4
212	        );
213	        // Nothing new: a no-op step.
214	        assert_eq!(ing.step().unwrap(), StepStats::default());
215	    }
216	
217	    #[test]
218	    fn resumes_from_persisted_offset_without_duplicates() {
219	        let tmp = tempfile::tempdir().unwrap();
220	        let log = tmp.path().join("events.jsonl");
221	        let db = tmp.path().join("b.db");
222	        let mut w = LogWriter::open(&log).unwrap();
223	        for i in 0..10 {
224	            w.append(&ev(i * 6000, "a")).unwrap();
