        t = l.typ(t + 100, k, "~", "git status\n");
        l.key(t, k, "~", "Up", &[]);
        t = l.typ(t + 100, k, "~", " -s");
        t = l.typ(t + 5_000, "notes", "n", " again");
        l.key(t, "notes", "n", "a", &[Mod::Ctrl]);
        t = l.typ(t + 100, "notes", "n", "replaced");
        l.key(t, "notes", "n", "z", &[Mod::Ctrl]);
        t = l.typ(t + 40_000, k, "~", "\n");
        l.typ(t + 100, "notes", "n", "!");
