        fn typ(&mut self, ts: Millis, app: &str, win: &str, s: &str) -> Millis {
            let mut t = ts;
            for c in s.chars() {
                let k = match c {
                    '\n' => "Enter".to_string(),
                    '\u{8}' => "Backspace".to_string(),
                    c => c.to_string(),
                };
                self.key(t, app, win, &k, &[]);
                t += 100;
