        let mut l = Log::new();
        let t = l.typ(T0, "notes", "todo", "the cat");
        // 31 s later, in the same window: a new session.
        l.typ(t + 31_000, "notes", "todo", "\u{8}\u{8}\u{8}dog");
        let mut ing = l.ingester("b.db");
        run(&mut ing, clock_late);
        let s = sessions(ing.connection());
        assert_eq!(s.len(), 2);
