/// Starts `brain run` on `data` (stopped with SIGTERM when dropped).
pub fn start_brain(data: &Path) -> Kill {
    Kill(
        Command::new(env!("CARGO_BIN_EXE_brain"))
            .args(["run", "--data-dir"])
            .arg(data)
            .stdout(Stdio::null())
            .stderr(Stdio::null())
            .spawn()
            .unwrap(),
    )
