    assert_eq!(v["at"], Value::Null);
    assert_local(&v["from"]);
    let s = &v["sessions"][0];
    assert_eq!((s["session_id"].as_str(), s["window"].as_str()), (Some("1"), Some("notes.md — Kate")));
