struct WorkspaceEditors {
    open: Vec<PathBuf>,
    history: Vec<PathBuf>,
}

impl WorkspaceEditors {
    fn load(config: &Path, root: &str) -> Self {
        let mut w = WorkspaceEditors::default();
        let Ok(rd) = std::fs::read_dir(config.join("User/workspaceStorage")) else {
