        };
        for e in rd.flatten().take(5000) {
            let dir = e.path();
            let folder = read_json(&dir.join("workspace.json"))
                .and_then(|v| v.get("folder").and_then(|f| f.as_str()).and_then(file_uri_to_path));
            if folder.is_none_or(|f| f.file_name().and_then(|n| n.to_str()) != Some(root)) {
                continue;
