            if let Some(v) = read_state_value(&db, "memento/workbench.parts.editor") {
                w.open.extend(file_uris_in(&v));
            }
            if let Some(v) = read_state_value(&db, "history.entries") {
                w.history.extend(file_uris_in(&v));
            }
        }
        w
    }
