/// Every `file:///...` URI in a piece of (possibly nested, escaped) JSON, as
/// local paths.
fn file_uris_in(text: &str) -> Vec<PathBuf> {
    text.match_indices("file:///")
        .filter_map(|(i, _)| {
            let rest = &text[i..];
            let end = rest
                .find(|c: char| c == '"' || c == '\\\\' || c.is_whitespace())
                .unwrap_or(rest.len());
            file_uri_to_path(&rest[..end])
        })
        .collect()
}

