        .unwrap_or_else(|| (vec![true; a_mid.len()], vec![true; b_mid.len()]));

    let mut ops: Vec<Op> = (0..prefix).map(|i| Op::Equal(i, i)).collect();
    let (mut i, mut j) = (0, 0);
