            ops.push(Op::Insert(prefix + j));
            j += 1;
        } else {
            ops.push(Op::Equal(prefix + i, prefix + j));
            i += 1;
            j += 1;
        }
    }
    let (a_end, b_end) = (a.len() - suffix, b.len() - suffix);
    ops.extend((0..suffix).map(|k| Op::Equal(a_end + k, b_end + k)));
