            .iter()
            .filter(|op| !matches!(op, Op::Delete(_)))
            .count();
        let a_len = slice.iter().filter(|op| !matches!(op, Op::Insert(_))).count();
        let b_len = slice.iter().filter(|op| !matches!(op, Op::Delete(_))).count();
        out.push_str(&format!(
            "@@ -{} +{} @@\\n",
            hunk_range(a_start, a_len),
            hunk_range(b_start, b_len)
