use std::process::Command;
#[test]
fn compare_with_git() {
    let dir = std::path::Path::new("/tmp/claude-1000/difftest");
    let mut seed: u64 = 42;
    let mut rnd = |n: u64| { seed ^= seed << 13; seed ^= seed >> 7; seed ^= seed << 17; seed % n };
    let mut mismatches = 0;
    for case in 0..300 {
        let n = 1 + rnd(40) as usize;
        let a: Vec<String> = (0..n).map(|i| format!("line {i} {}", i % 7)).collect();
        let mut b = a.clone();
        for _ in 0..(1 + rnd(4)) {
            match rnd(3) {
                0 if !b.is_empty() => { let k = rnd(b.len() as u64) as usize; b.remove(k); }
                1 => { let k = rnd(b.len() as u64 + 1) as usize; b.insert(k, format!("new {case} {}", rnd(1000))); }
                _ if !b.is_empty() => { let k = rnd(b.len() as u64) as usize; b[k] = format!("changed {case} {}", rnd(1000)); }
                _ => {}
            }
        }
        let (ta, tb) = (a.join("\n") + "\n", b.join("\n") + "\n");
        std::fs::write(dir.join("old"), &ta).unwrap();
        std::fs::write(dir.join("new"), &tb).unwrap();
        let out = Command::new("git").args(["diff", "--no-index", "-U3", "--no-color", "--diff-algorithm=myers"]).arg(dir.join("old")).arg(dir.join("new")).output().unwrap();
        let git = String::from_utf8(out.stdout).unwrap();
        let git_hunks: String = git.lines().skip_while(|l| !l.starts_with("@@")).map(|l| {
            // git appends the function context after the second @@; drop it.
            if l.starts_with("@@") { let e = l[2..].find("@@").unwrap() + 4; l[..e].to_string() } else { l.to_string() }
        }).collect::<Vec<_>>().join("\n");
        let ours = brain::reconstruct::vscode::unified_diff(&ta, &tb, "f", 3);
        let ours_hunks: String = ours.lines().skip(2).collect::<Vec<_>>().join("\n");
        if git_hunks != ours_hunks { mismatches += 1; if mismatches <= 2 { println!("CASE {case}\nGIT:\n{git_hunks}\nOURS:\n{ours_hunks}\n"); } }
    }
    println!("mismatches: {mismatches} / 300");
}
EOF
