        let ours = brain::reconstruct::vscode::unified_diff(&ta, &tb, "f", 3);
        let ours_hunks: String = ours.lines().skip(2).collect::<Vec<_>>().join("\n");
        if git_hunks != ours_hunks { mismatches += 1; if example.is_none() { example = Some(format!("OLD:\n{ta}NEW:\n{tb}GIT:\n{git_hunks}\nOURS:\n{ours_hunks}")); } }
    }
    (mismatches, example)
}
