/// Moves each run of only insertions (or only deletions) as far down as
/// possible while the text stays the same: when the line after the run
/// equals the run's first line, the run can start one line later. This is
/// how git places ambiguous changes, e.g. a function added after an
/// existing `}` shows as added after it, not before it.
fn slide_down(ops: &mut [Op], a: &[&str], b: &[&str]) {
    let mut start = 0;
    while start < ops.len() {
        let insert = matches!(ops[start], Op::Insert(_));
        let delete = matches!(ops[start], Op::Delete(_));
        if !insert && !delete {
            start += 1;
            continue;
        }
        let same = |op: &Op| matches!(op, Op::Insert(_)) == insert && !matches!(op, Op::Equal(..));
        let mut end = start;
        while end < ops.len() && same(&ops[end]) {
            end += 1;
        }
        // Only pure runs between equal lines slide.
        let pure = start == 0 || matches!(ops[start - 1], Op::Equal(..));
        while pure && end < ops.len() {
            let Op::Equal(i, j) = ops[end] else { break };
            let (first, next) = match ops[start] {
                Op::Insert(j0) => (b[j0], b[j]),
                Op::Delete(i0) => (a[i0], a[i]),
                Op::Equal(..) => unreachable!(),
            };
            if first != next {
                break;
            }
            // Rotate: the equal line moves before the run, the run moves down.
            ops[start] = match ops[start] {
                Op::Insert(j0) => Op::Equal(i, j0),
                Op::Delete(i0) => Op::Equal(i0, j),
                Op::Equal(..) => unreachable!(),
            };
            ops[start..=end].rotate_left(1);
            let moved = ops[start..end].to_vec();
            ops[end] = match moved.last().copied() {
                Some(Op::Insert(jl)) => Op::Insert(jl + 1),
                Some(Op::Delete(il)) => Op::Delete(il + 1),
                _ => unreachable!(),
            };
            let _ = moved;
            start += 1;
            end += 1;
        }
        start = end.max(start + 1);
    }
}"""
