    fn lock(&self) -> std::sync::MutexGuard<'_, Inner> {
        // A panic while holding the lock cannot leave the log half-written
        // (appends are single writes), so recovering from poisoning is safe.
        self.inner.lock().unwrap_or_else(|p| p.into_inner())
    }

    fn append(&self, inner: &mut Inner, event: Event) {
        if let Err(e) = inner.log.append(&event) {
            // Never take capture down over a write error (for example, the disk
            // is full). Report the first one, then every 1000th.
            let n = self.write_errors.fetch_add(1, Ordering::Relaxed);
            if n.is_multiple_of(1000) {
                eprintln!(
                    "brain: failed to write capture log ({} errors so far): {e:#}",
                    n + 1
                );
            }
        }
    }

    pub fn focus(&self) -> Focus {
        self.lock().focus.clone()
    }

    /// Records a focus change. A no-op if neither app nor window changed.
    /// A window was activated (`renamed: false`) or the active window's title
    /// changed (`renamed: true`).
    pub fn set_focus(&self, app: &str, window: &str, renamed: bool) {
        let mut g = self.lock();
        if g.focus.app == app && g.focus.window == window {
            return;
        }
        g.focus = Focus {
            app: app.to_string(),
            window: window.to_string(),
        };
        if g.paused {
            return; // recorded on unlock, when it matters
        }
        let ev = Event {
            ts: now_ms(),
            app: app.to_string(),
            kind: EventKind::Focus {
                window: window.to_string(),
                renamed,
            },
        };
        self.append(&mut g, ev);
    }

    /// Pauses or resumes recording of input (screen lock). Lifecycle markers
    /// are still written.
    pub fn set_paused(&self, paused: bool) {
        let mut g = self.lock();
        if g.paused == paused {
            return;
        }
        g.paused = paused;
        let app = g.focus.app.clone();
        let state = if paused {
            SystemState::Lock
        } else {
            SystemState::Unlock
        };
        self.append(
            &mut g,
            Event {
                ts: now_ms(),
                app: app.clone(),
                kind: EventKind::System { state },
            },
        );
        if !paused {
            // Re-state the focus so readers know the context after the gap.
            let window = g.focus.window.clone();
            self.append(
                &mut g,
                Event {
                    ts: now_ms(),
                    app,
                    kind: EventKind::Focus {
                        window,
                        renamed: false,
                    },
                },
            );
        }
    }

    pub fn system(&self, state: SystemState) {
    // inherits the mask and only `wait_for_signal` on the main thread sees them.
    let signals = block_termination_signals()?;
    // Everything brain writes is private to the user.
    // SAFETY: umask is always safe to call.
    unsafe { libc::umask(0o077) };

    data_dir.create()?;
    let _lock = data_dir.lock_exclusive()?;
    let log = LogWriter::open(&data_dir.log_path())?;
    let conn = store::open_writer(&data_dir.db_path())?;
    let tier2: Option<Box<dyn Tier2Snapshotter>> = if opts.vscode_replay {
        let snaps = VsCodeSnapshots::new(data_dir.vscode_dir().join("snapshots"))?;
        snaps.prune(&conn)?;
        Some(Box::new(snaps))
    } else {
        None
    };
    let ingester = Ingester::with_tier2(conn, &data_dir.log_path(), tier2)?;
    let tier2_worker = if opts.vscode_replay {
        let (tx, rx) = std::sync::mpsc::channel();
        let worker = Tier2Worker::spawn(
            data_dir.db_path(),
            data_dir.log_path(),
            data_dir.vscode_dir(),
            tx,
        )?;
        eprintln!("brain: VS Code replay (tier 2) is on");
        Some((worker, rx))
    } else {
        None
    };

    let source = match opts.synthetic_rate {
        Some(rate) => start_synthetic(log, rate)?,
        None => start_capture(data_dir, log)?,
    };
    let recorder = source.recorder().clone();
    let ingest = IngestThread::spawn(ingester, recorder.clone(), tier2_worker)?;

    let sig = wait_for_signal(&signals)?;
    eprintln!("brain: received signal {sig}, stopping");

    source.stop();
    recorder.system(SystemState::Stop);
    ingest.stop();
    Ok(())
}

